function UIActivityPromoterPopup:__init()
    self.type = PromoterType.OLD
end

function UIActivityPromoterPopup:__delete()
end

function UIActivityPromoterPopup:Awake()

    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end

    self.shareType_ = Constants.ShareType.PROMOTER -- 14

    self.activityUuid = argument.activityUuid
    self.spreadDojoData = argument.spreadDojoData
    if argument.type then
        self.type = checkNumber(argument.type)
    end
    self.url = tostring(self.spreadDojoData.shareUrl) -- 要分享的 url 链接

    ---@type ShareMessagesVo
    self.shareMessagesVo = CfUtils.GetCfVo(AutoIds.IdSetting953, "ShareMessagesVo", self.shareType_ ) or {}


    -- share defines
    self.shareDefines_ = {}
    for _, defines in pairs(ShareChannelDefines) do
        self.shareDefines_[defines.channel] = {
            channel  = defines.channel,
            title    = self.shareMessagesVo[defines.voTitle],
            descr    = self.shareMessagesVo[defines.voDescr],
            link     = self.shareMessagesVo[defines.voLink],
            show     = self.shareMessagesVo[defines.voShow],
            gName    = self.shareMessagesVo[defines.voGName],
            gSection = self.shareMessagesVo[defines.voGSection],
        }
    end

    --- =======
    ---@type SDKService
    local SDKService = import('Game.Entry.SDKService')
    local notDmm = (not SDKService:GetInstance():IsDmm())
    if self.shareMessagesVo.facebookShow == 1  and notDmm then
        self:AddShareBtn( datas.facebook_101 )
    end

    if self.shareMessagesVo.twitterShow == 1 then
        self:AddShareBtn( datas.twitter_102 )
    end

    if self.shareMessagesVo.instagramShow == 1 then
        self:AddShareBtn( datas.ins_103 )
    end
    if self.shareMessagesVo.lineShow == 1 and notDmm then
        self:AddShareBtn( datas.line_104 )
    end

    if self.shareMessagesVo.discordShow == 1 then
        self:AddShareBtn( datas.discord_105 )
    end

    -----
    SetButtonAction(self.BtnCopy, Bind(self, self._OnClickBtnCopy))

    CfUtils.FillText( self.TxtTips.gameObject, localize('今日剩余可被助力次数：<color=#FF26A2>_Times_</color>', {_Times_=tostring( self.spreadDojoData.remainingAssistanceTimes )}) )
end


