function UIActivityPromoterPopup:_OnClickBtnCopy()
    CS.Engine.Http.DeviceID.CopyToClipboard( self.url )
    GameUtils.Toast(localize("复制成功")) -- 飘字
end


function UIActivityPromoterPopup:AddShareBtn( data_ )

    local baseShareBtn = self.ShareNode:Find("BtnShare")
    if isNull(baseShareBtn) then 
        printError("没找到 BtnShare")
        return
    end 

    local newBtn = Object.Instantiate(baseShareBtn.gameObject, self.ShareNode.transform )
    CfUtils.SetActive(newBtn, true)

    local ImgIcon = newBtn.transform:Find("ImgIcon")
    local TxtTitle = newBtn.transform:Find("TxtTitle")


    CfUtils.FillImage(ImgIcon.gameObject , ActivityUtils.GetImageFullPath( data_.picPath ) )
    CfUtils.FillText( TxtTitle, data_.txt )


    SetButtonAction(newBtn, function()
        --printError("分享")
        xRecord.record( "6-008", "click_spead_link" ) -- 打点
        self:OnClickToShareButtonHandler_( data_.key  )
    end)

end




---@param key_ string
function UIActivityPromoterPopup:OnClickToShareButtonHandler_( key_ )
    local channelDefine = ShareChannelDefines[key_] or {}

    local shareChannel  = channelDefine.channel
    local isSDKVideo    = channelDefine.sdkVideo == true
    local packageName   = channelDefine.packageName
    local className     = channelDefine.className

    local shareDefine   = self.shareDefines_[shareChannel] or {}
    local shareTitle    = shareDefine.title or ''
    local shareDesc     = shareDefine.descr or ''
    --local shareDesc     = ''
    local shareLink     = self.url                      -- 需要分享 链接
    local groupName     = shareDefine.gName or ''
    local groupSection  = shareDefine.gSection or ''
    local filePath      = "" -- 不分享图片

    if KTool.IsMobile() then
        local kTool = CS.Engine.Lib.KTool
        -- sdk分享 链接 和 desc
        if shareChannel == Constants.ShareChannel.FB and kTool.UNITY_IOS() then
            local shareType = 50 
            if string.len(filePath) > 0  then
                shareType = 51
            else 
                shareType = 50    
            end
            local t = {
                type = shareType,
                imgPath = filePath or "",
                title = shareTitle or "",
                content = shareDesc or "",
                url = shareLink or "",
                groupName = groupName or "",
                groupSection = groupSection or "",
            }
            local ProxyPluginName = "PlatformProxy"
            local SDKCenter = CS.Game.Native.MobileSDK.SDKCenter
            SDKCenter.InvokePlugin(ProxyPluginName, "share", table.serialize(t))
        else 
            SDKService:GetInstance():Share(shareChannel, filePath, shareTitle, shareDesc, shareLink, groupName, groupSection)    
        end
        
        self:OnShareSucceedCallback_()

    else
        print(string.fmt('<color=#CC6699>[shareType = %1] %2</color>', tostring(self.shareType_), table.serialize({
            shareId = tostring(self.shareMessagesVo.id),
            file    = filePath,
            channel = shareChannel,
            title   = shareTitle,
            descr   = shareDesc,
            link    = shareLink,
        })))
        if CS.UnityEngine.Application.isEditor then
            -- 开发测试用，所以不要翻译
            GameUtils.Toast('假装分享成功')
            -- 编辑器环境下测试用
            self:OnShareSucceedCallback_()
        else
            GameUtils.Toast(localize('请移动至手机端进行分享'))
        end
    end
end



function UIActivityPromoterPopup:OnShareSucceedCallback_()

    -- 如果今天已经分享过了, 无法领取奖励:
    if self.spreadDojoData.isShare ~= 0 then 
        print("外观推广员活动 今天已经分享过了")
        return
    end 
    local interfacePath = "Activity/spreadShare"
    if self.type == PromoterType.NEW then
        interfacePath = "Activity2/spreadShare"
    end
    GameUtils.Request(interfacePath , {activityUuid = self.activityUuid}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            --printError("data = " .. table.dump(response.data) )

            Events.Broadcast(Constants.EventNames.PromoterRefresh)

            -- 领取宝箱数据, 
            GoodsUtils.DrawRewards( response.data.rewards )

            -- 播放窗口动画:
            UIModule.OpenDialog({ 
                id = Constants.UITypeIds.UICommonRewardPop, 
                parameters = { rewards = response.data.rewards } 
            })
        end
    end)
end






return UIActivityPromoterPopup
 
 